%script to package up BTB files for distribution

GENERATE_DOCUMENTATION = 1;
EDIT_FILES = 0;
DISTRIBUTE_TO_ATONAL = 1;

home_path = '/home/stefan/';
relative_dist_path = 'btb/';
dist_path = fullfile(home_path,relative_dist_path);
www_path = '/var/www/html/projects/musical_spaces/rhythm/btb/';
dist_file = 'btb_v1.0.tar.gz';
log_file = '/home/stefan/btbfiles.log';
readme_file = '/home/stefan/svn/private/matlab/projects/rhythm_profiler/dist/README.txt';


colormap_list = {'/afs/cmb.ucdavis.edu/share/matlab/janata/colormaps/new_seismic'};

file_list = {
    'ensemble_init_data_struct',... 
    'check_stim_dirs',...
    'check_anal_exist',...
    'mkstruct',...
    'check_dir',...
    'init_aud',...
    'params_aud',...
    'new_aud',...
    'init_midi',...
    'nmat2aud',...
    'nmat_columns',...
    'params_pp',...
    'params_ci',...
    'params_ani',...
    'calc_ani',...
    'params_ani',...
    'init_ani_struct',...
    'create_ipem_tmpdir',...
    'construct_analfname',...
    'rhythm_profiler',...
    'resonatorBanks',...
    'resonatorEnergy',...
    'init_rp_struct',...
    'rp_paramGroups',...
    'ipem_proc_series',...
    'ani_paramGroups',...
    'get_rpPlotInfo',...
    'rp_figure',...
    'rotateyticklabel',...
    'get_resonPeakInfo',...
    'find_peaks',...
    'peak_widths',...
    'plot_rpResonOutput',...
    'plot_rhythmProfile',...
    'plot_rpInput',...
    'plot_rpResonEnergy',...
    'plot_rpMeanResonEnergy',...
    'plot_findPeaks',...
    'plot_rpBandSigs',...
    'plot_dir_rhythm_profile',...
    'get_axhandle',...
    'get_rp_peakWidths',...
    'set_var_col_const',...
    'javamidi2tr',...
    'Midi2tr.java',...
    'TrackInfo.java',...
    'btb',...
    };

pathRep = {'/home/stefan/svn/public/matlab/database','utils';...
	   '/home/stefan/svn/public/matlab/utils','utils';...
	   '/home/stefan/svn/private/matlab/event_objects','event_objects';...
	   '/home/stefan/svn/private/matlab/ipem','proc';...
	   '/home/stefan/svn/private/matlab/ipem/rp_modules','rp_modules';...
	   '/home/stefan/svn/private/matlab/projects/rhythm_profiler/params','proc/params';...
	   '/home/stefan/svn/private/matlab/projects/rhythm_profiler','.';...
	   '/home/stefan/svn/thirdparty/matlab/miditoolbox','midi';...
	   '/home/stefan/svn/private/matlab/utils/converters','utils';...
       };

if(exist(dist_path,'dir'))
  eval(['!rm -r ' dist_path]);
end

check_dir(dist_path,1);
fid = fopen(log_file,'w');


nfiles = length(file_list);
for ifile = 1:nfiles
  filesource_list{ifile} = which(file_list{ifile});
  fprintf(fid,'%s\n',filesource_list{ifile});
end

if(EDIT_FILES)
  eval(['!emacs ' cell2str(filesource_list,' ') ' &']);
else
  %go ahead and package for distribution if not editing files.
  filedest_list = filesource_list;
  for iPath = 1:size(pathRep,1)
    filedest_list = strrep(filedest_list,pathRep{iPath,1},pathRep{iPath,2});  
  end
  filedest_list = strcat(dist_path,filedest_list);

  for ifile = 1:nfiles
    [pth,f,e] = fileparts(filedest_list{ifile});
    if(~exist(pth,'dir'))
      mkdir(pth);
    end
    copy_string = ['!cp ' filesource_list{ifile} ' ' filedest_list{ifile}];
    eval(copy_string);
  end
  
  %create documentation
  if(GENERATE_DOCUMENTATION)
    cd(home_path);
    m2html('mfiles',relative_dist_path,'htmldir',fullfile(home_path,'documentation'),'recursive','on');
    eval(['!mv ' fullfile(home_path,'documentation') ' '  relative_dist_path]);
    %deleting old documentation
    if(DISTRIBUTE_TO_ATONAL)
      eval(['!ssh stefan@chromatic.cmb.ucdavis.edu rm -r ' fullfile(www_path,'documentation')]);
      eval(['!scp -r ' fullfile(relative_dist_path,'documentation') ' chromatic.cmb.ucdavis.edu:' www_path]);
    end
  end
  
  %copy the readme file
  eval(['!cp ' readme_file ' ' dist_path]);

  %copy colormaps
  eval(['!cp ' cell2str(colormap_list,' ') ' ' fullfile(dist_path,'utils')]);
  
  %tarball everything
  eval(['!tar -C ' home_path ' -cf ' fullfile(home_path,dist_file) ' ' relative_dist_path ' --gzip']);
  
  if(DISTRIBUTE_TO_ATONAL)
    %copy the tarball to atonal
    eval(['!scp ' fullfile(home_path,dist_file) ' chromatic.cmb.ucdavis.edu:' www_path]);
  end
  
end
  
fclose(fid);
